sys_ux_client_script.script:
function handler({api, event, helpers, imports}) {

    if (api.state.isRunning) {
        return;
    }

    const elapsedBeforePause = api.state.elapsedTime;

    const parts = elapsedBeforePause.split(':');
    const hours = Number(parts[0]);
    const minutes = Number(parts[1]);
    const secondsParts = parts[2].split('.');
    const seconds = Number(secondsParts[0]);
    const milliseconds = Number(secondsParts[1]);

    const previousElapsed =
        (hours * 3600000) +
        (minutes * 60000) +
        (seconds * 1000) +
        milliseconds;

    const startTime = Date.now() - previousElapsed;

    api.setState('isRunning', true);

    const intervalId = helpers.timing.setInterval(() => {

        const elapsed = Date.now() - startTime;

        const hours = Math.floor(elapsed / 3600000);
        const minutes = Math.floor((elapsed % 3600000) / 60000);
        const seconds = Math.floor((elapsed % 60000) / 1000);
        const milliseconds = elapsed % 1000;

        const display =
            String(hours).padStart(2, '0') + ':' +
            String(minutes).padStart(2, '0') + ':' +
            String(seconds).padStart(2, '0') + '.' +
            String(milliseconds).padStart(3, '0');

        api.setState('elapsedTime', display);

    }, 10);

    api.setState('intervalId', intervalId);
}
